s = open('24.txt').readline().strip()

best = left = k = 0
for right in range(len(s)):
    if s[right] == 'A':
        k += 1
    while k > 2:
        if s[left] == 'A':
            k -= 1
        left += 1
    best = max(best, right - left + 1)
print(best)

s = open('24.txt').readline().strip()

counts = {}
for i in range(1, len(s)):
    if s[i - 1] == 'B':
        ch = s[i]
        counts[ch] = counts.get(ch, 0) + 1
winner = max(sorted(counts), key=counts.get)
print(winner, counts[winner])

